query LoanSnapshot($input: LoansInput) {
  liqwid {
    data {
      loans(input: $input) {
        totalCount
        page
        perPage
        pagesCount
        results {
          marketId
          amount(input: { currency: USD })
          collateral(input: { currency: USD })
          healthFactor
          LTV
          APY
        }
      }
    }
  }
}
